// Deny overrides Allow - Example
// Policy 1: Allows S3 read access
{
  "Effect": "Allow",
  "Action": ["s3:GetObject"],
  "Resource": ["arn:aws:s3:::my-bucket/*"]
}

// Policy 2: Denies access to specific folder
{
  "Effect": "Deny",
  "Action": ["s3:GetObject"],
  "Resource": ["arn:aws:s3:::my-bucket/secret/*"]
}
// Result: User can access all files EXCEPT secret folder

// Implicit Deny - No policy allows access
// Result: Access denied by default
